class DataLoadError extends Error {constructor(label,cause){super(label+': '+cause.message);this.cause=cause;}}
class SourceLoadError extends DataLoadError { constructor(source,cause){super('Не удалось загрузить ряд ЕМИСС '+sourceId(source),cause);this.source=source;} }
export async function loadSourceObservations(source,fetcher=globalThis.fetch){
 const path=source?.downloads?.observations;
 if(!path)return [...arr(source?.national),...arr(source?.regional_history),...arr(source?.other_territories)];
 const key=String(path).replace(/^\.\//,'');
 return observationCache.getOrCreate(PROJECT+':observations:'+key,async()=>{
  try{
   const response=await fetcher('./'+key);
   if(!response.ok)throw new Error('HTTP '+response.status);
   const data=await response.json();
   if(String(data.source_id)!==sourceId(source))throw new Error('Идентификатор источника не соответствует выбранному ряду');
   if(!Array.isArray(data.observations))throw new Error('В ответе отсутствует таблица наблюдений');
   return data.observations;
  }catch(error){throw new SourceLoadError(source,error);}
 });
}
const categoryKey=p=>typeof p?.category==='object'?Object.entries(p.category).sort(([a],[b])=>a.localeCompare(b)).map(([key,val])=>key+':'+val).join(';'):String(p?.category||'');
