function domainsPage(ctx){
 const root=start(ctx),data=ctx.longlife.documentary?.text||{},frames=arr(data.frames),rows=arr(data.domainEvidence),id=rows.some(r=>r.domain_id===ctx.state.frame)?ctx.state.frame:'clinical_health',selected=rows.find(r=>r.domain_id===id)||rows[0],nodes=arr(ctx.longlife.documentary?.network?.nodes),docMap=new Map(arr(data.documents).map(d=>[d.document_id,d]));
 append(root,toolbar(select('Содержательная область',rows.map(r=>[r.domain_id,r.domain_name]),selected?.domain_id,v=>ctx.set({frame:v}))),note('Матрица содержит документальные свидетельства. Число упоминаний и наличие словарного маркера не превращаются в сводный балл эффективности. Отсутствие маркера требует чтения документа.'));
 if(selected){let ids=[];try{ids=JSON.parse(selected.evidence_node_ids_json||'[]');}catch{}const evidence=nodes.filter(n=>ids.includes(n.node_id));append(root,stats([['Цели с маркером',fmt(num(selected.goal_nodes),0),'документальные карточки'],['Задачи с маркером',fmt(num(selected.task_nodes),0),'документальные карточки'],['Результаты с маркером',fmt(num(selected.result_nodes),0),'не сведения об исполнении'],['Связанные статистические коды',fmt(num(selected.approved_statistical_codes),0),'проверенные соответствия']]),panel(selected.domain_name,'Карточки документа, на которых основана матрица.',table(evidence.map(n=>({kind:kindLabel(n.kind),title:n.title,document:documentName(docMap.get(n.document_id)),url:n.source_url,locator:n.source_xpath||n.source_card_id,id:n.node_id})),[{key:'kind',label:'Тип'},{key:'title',label:'Свидетельство'},{key:'document',label:'Документ'},{key:'url',label:'Источник',render:url=>a('Открыть',url)},{key:'locator',label:'Указатель'}],{filename:'longlife-domain-evidence.csv',pageSize:10,onSelect:r=>ctx.go('network',{layer:'documentary',node:r.id})})));
 }
 append(root,panel('Обзор '+rows.length+' областей','Показатели пересекаются между областями; их нельзя складывать в сумму уникальных мер.',table(rows.map(r=>({...r,goals:num(r.goal_nodes),tasks:num(r.task_nodes),results:num(r.result_nodes),indicators:num(r.indicator_nodes),codes:num(r.approved_statistical_codes)})),[{key:'domain_name',label:'Область'},{key:'goals',label:'Цели',numeric:true,decimals:0},{key:'tasks',label:'Задачи',numeric:true,decimals:0},{key:'results',label:'Результаты',numeric:true,decimals:0},{key:'indicators',label:'Показатели',numeric:true,decimals:0},{key:'codes',label:'Статистические коды',numeric:true,decimals:0}],{filename:'longlife-domains.csv',pageSize:18,onSelect:r=>ctx.set({frame:r.domain_id})})));
 return end(ctx,root);
}

export async function longlifePage(ctx){
 const renderers={overview,framework,structure:architecture,logic,audit,targets,map:mapPage,regions:regionsPage,finance,population,causal,proposals,methods,explorer,network:networkPage,texts:textsPage,domains:domainsPage,projections:scenarios,lab,library,updates};
 try{return await(renderers[ctx.state.page]||overview)(ctx);}
 catch(error){
  if(!(error instanceof DataLoadError))throw error;
  const root=start(ctx),retry=button('Повторить загрузку',async()=>{retry.disabled=true;retry.textContent='Загрузка…';try{const replacement=await longlifePage(ctx);if(root.isConnected)root.replaceWith(replacement);}finally{retry.disabled=false;retry.textContent='Повторить загрузку';}},'button primary','reset');
  append(root,panel('Источник временно не загрузился',null,h('div',{class:'longlife-load-error',role:'alert'},para(error.message),para('Выбранные фильтры сохранены. Повторная попытка заново обращается к файлу источника.'),retry)),a('Открыть библиотеку источников',href('library')));
  return end(ctx,root);
 }
}


